<?php
require __DIR__.'/config.php';$me=require_auth();$cid=(int)$me['customer_id'];$errors=[];$notice='';$post=$_POST;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'');try{
    if($action==='add'){$type=(string)($_POST['target_type']??'');$nickname=trim((string)($_POST['nickname']??''));if(strlen($nickname)>50)throw new RuntimeException();$pdo=db();$pdo->beginTransaction();if($type==='internal'){$number=trim((string)($_POST['account_number']??''));if(!preg_match('/^[A-Za-z0-9]{6,20}$/',$number))throw new RuntimeException();$s=$pdo->prepare("SELECT account_id FROM accounts WHERE account_number=? AND status='active'");$s->execute([$number]);$targetId=(int)$s->fetchColumn();if(!$targetId||owned_account($pdo,$cid,$targetId))throw new RuntimeException();$dupe=$pdo->prepare('SELECT 1 FROM beneficiaries WHERE customer_id=? AND target_account_id=?');$dupe->execute([$cid,$targetId]);if($dupe->fetchColumn())throw new RuntimeException();$s=$pdo->prepare('INSERT INTO beneficiaries (customer_id,nickname,target_account_id,external_account_id) VALUES (?,?,?,NULL)');$s->execute([$cid,$nickname?:null,$targetId]);}elseif($type==='external'){$data=['account_number'=>trim((string)($_POST['external_account_number']??'')),'account_name'=>trim((string)($_POST['external_account_name']??'')),'bank_name'=>trim((string)($_POST['bank_name']??'')),'routing_number'=>trim((string)($_POST['routing_number']??''))];if(in_array('',array_values($data),true)||strlen($data['account_number'])>30||strlen($data['account_name'])>150||strlen($data['bank_name'])>100||strlen($data['routing_number'])>20)throw new RuntimeException();$s=$pdo->prepare('SELECT external_account_id FROM external_accounts WHERE bank_name=? AND routing_number=? AND account_number=?');$s->execute([$data['bank_name'],$data['routing_number'],$data['account_number']]);$externalId=(int)($s->fetchColumn()?:0);if(!$externalId){$s=$pdo->prepare('INSERT INTO external_accounts (account_number,account_name,bank_name,routing_number) VALUES (?,?,?,?)');$s->execute([$data['account_number'],$data['account_name'],$data['bank_name'],$data['routing_number']]);$externalId=(int)$pdo->lastInsertId();}$s=$pdo->prepare('SELECT 1 FROM beneficiaries WHERE customer_id=? AND external_account_id=?');$s->execute([$cid,$externalId]);if($s->fetchColumn())throw new RuntimeException();$s=$pdo->prepare('INSERT INTO beneficiaries (customer_id,nickname,target_account_id,external_account_id) VALUES (?,?,NULL,?)');$s->execute([$cid,$nickname?:null,$externalId]);}else throw new RuntimeException();$pdo->commit();flash('Beneficiary saved.');go('beneficiaries.php');}
    elseif($action==='edit'){$id=filter_var($_POST['beneficiary_id']??null,FILTER_VALIDATE_INT);$nickname=trim((string)($_POST['nickname']??''));if(!$id||strlen($nickname)>50)throw new RuntimeException();$s=db()->prepare('UPDATE beneficiaries SET nickname=? WHERE beneficiary_id=? AND customer_id=?');$s->execute([$nickname?:null,$id,$cid]);if($s->rowCount()===0){$s=db()->prepare('SELECT 1 FROM beneficiaries WHERE beneficiary_id=? AND customer_id=?');$s->execute([$id,$cid]);if(!$s->fetchColumn())throw new RuntimeException();}flash('Beneficiary nickname updated.');go('beneficiaries.php');}
    elseif($action==='delete'){$id=filter_var($_POST['beneficiary_id']??null,FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException();$s=db()->prepare('DELETE FROM beneficiaries WHERE beneficiary_id=? AND customer_id=?');$s->execute([$id,$cid]);if(!$s->rowCount())throw new RuntimeException();flash('Beneficiary removed.');go('beneficiaries.php');}
    else throw new RuntimeException();
}catch(Throwable $x){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$errors[]='The beneficiary could not be saved. Check the details and make sure it is not already on your list.';}}
$s=db()->prepare('SELECT b.beneficiary_id,b.nickname,b.added_at,a.account_title,a.account_number,x.account_name,x.account_number AS external_number,x.bank_name,x.routing_number FROM beneficiaries b LEFT JOIN accounts a ON a.account_id=b.target_account_id LEFT JOIN external_accounts x ON x.external_account_id=b.external_account_id WHERE b.customer_id=? ORDER BY b.added_at DESC,b.beneficiary_id DESC');$s->execute([$cid]);$rows=$s->fetchAll();render_start('Beneficiaries');?><section class="page-heading"><div class="eyebrow dark">Saved destinations</div><h1>Beneficiaries</h1><p>Save trusted BankEase and external bank destinations for faster transfers.</p></section><?php if($errors):?><div class="notice error" role="alert"><?php foreach($errors as $eText):?><p><?=e($eText)?></p><?php endforeach;?></div><?php endif;?><section class="beneficiary-grid"><?php foreach($rows as $b):?><article class="beneficiary-card"><div class="beneficiary-top"><span class="badge"><?=$b['external_number']?'External bank':'BankEase'?></span><span class="muted">Added <?=e(substr($b['added_at'],0,10))?></span></div><h2><?=e($b['nickname']?:($b['account_title']?:$b['account_name']))?></h2><?php if($b['external_number']):?><p><?=e($b['account_name'])?> · <?=e($b['bank_name'])?></p><p class="muted">Account •••• <?=e(substr($b['external_number'],-4))?> · Routing <?=e($b['routing_number'])?></p><?php else:?><p><?=e($b['account_title'])?></p><p class="muted">BankEase account •••• <?=e(substr($b['account_number'],-4))?></p><?php endif;?><form method="post" class="inline-edit"><?=csrf()?><input type="hidden" name="beneficiary_id" value="<?=$b['beneficiary_id']?>"><input type="hidden" name="action" value="edit"><label class="visually-hidden" for="nick<?=$b['beneficiary_id']?>">Nickname</label><input id="nick<?=$b['beneficiary_id']?>" name="nickname" maxlength="50" placeholder="Add or edit nickname" value="<?=e($b['nickname']??'')?>"><button class="button pale" type="submit">Save name</button></form><form method="post" class="delete-form" onsubmit="return confirm('Remove this beneficiary?')"><?=csrf()?><input type="hidden" name="beneficiary_id" value="<?=$b['beneficiary_id']?>"><button class="text-button" type="submit" name="action" value="delete">Remove beneficiary</button></form></article><?php endforeach;?><?php if(!$rows):?><div class="empty">You have no saved beneficiaries yet.</div><?php endif;?></section><section class="detail-card"><div class="eyebrow dark">Add a destination</div><h2>Save a beneficiary</h2><form method="post" class="beneficiary-add"><?=csrf()?><input type="hidden" name="action" value="add"><div class="field"><label for="target_type">Destination type</label><select name="target_type" id="target_type"><option value="internal">BankEase account</option><option value="external">External bank account</option></select></div><div class="field"><label for="nickname">Nickname <span class="muted">(optional)</span></label><input name="nickname" id="nickname" maxlength="50" value="<?=e($post['nickname']??'')?>"></div><div class="field beneficiary-internal"><label for="account_number">BankEase account number</label><input name="account_number" id="account_number" maxlength="20"></div><div class="beneficiary-external" hidden><div class="form-grid"><div class="field"><label for="external_account_name">Account holder name</label><input name="external_account_name" id="external_account_name" maxlength="150" disabled></div><div class="field"><label for="bank_name">Bank name</label><input name="bank_name" id="bank_name" maxlength="100" disabled></div><div class="field"><label for="external_account_number">Account number</label><input name="external_account_number" id="external_account_number" maxlength="30" disabled></div><div class="field"><label for="routing_number">Routing number</label><input name="routing_number" id="routing_number" maxlength="20" disabled></div></div></div><button class="button navy" type="submit">Save beneficiary</button></form></section><?php render_end();?>
